// README images (docs/screenshots, regenerated by scripts/screenshots.mjs): every image path exists, every screenshot comes in a
// light and a dark file with an alt text and a size cap, and the title carries the app icon. Synthetic README strings test the checker.
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const MAX_BYTES = 300 * 1024;
const SHOTS = 'docs/screenshots/';
const ICON = 'app/src-tauri/icons/128x128.png';
const SCREENS = ['dashboard', 'session', 'project', 'rules', 'settings', 'spawn'];

const attr = (tag, name) => new RegExp(`\\s${name}="([^"]*)"`, 'i').exec(tag)?.[1] ?? null;

/** Problems found in a README: `repo` = { exists(path), size(path) } on repo-relative paths. Empty array = fine. */
export function checkReadme(md, repo) {
  const problems = [];
  const title = md.split('\n')[0];
  if (!/^# /.test(title) || !title.includes(`src="${ICON}"`)) problems.push(`the title line has no ${ICON} icon`);

  const used = new Set(); // every path the README mentions, found or not
  const local = (p, what) => {
    used.add(p);
    if (/^[a-z][a-z0-9+.-]*:/i.test(p) || p.startsWith('//')) problems.push(`${what} ${p} is not a file in the repository`);
    else if (!repo.exists(p)) problems.push(`${what} ${p} does not exist`);
    else if (p.startsWith(SHOTS) && repo.size(p) > MAX_BYTES) problems.push(`${p} is over ${MAX_BYTES / 1024} KB`);
  };
  for (const [tag] of md.matchAll(/<img\b[^>]*>/gi)) {
    const src = attr(tag, 'src');
    if (src === null) { problems.push(`an <img> has no src: ${tag}`); continue; }
    local(src, 'src');
    if (src.startsWith(SHOTS) && !attr(tag, 'alt')?.trim()) problems.push(`${src} has no alt text`);
  }
  for (const [tag] of md.matchAll(/<source\b[^>]*>/gi)) {
    const set = attr(tag, 'srcset');
    if (set === null) problems.push(`a <source> has no srcset: ${tag}`); else local(set, 'srcset');
  }
  // each screenshot: <picture> with a dark source and a light img of the same name
  const pictures = [...md.matchAll(/<picture>([\s\S]*?)<\/picture>/gi)].map((m) => m[1]);
  for (const body of pictures) {
    const src = attr(/<img\b[^>]*>/i.exec(body)?.[0] ?? '', 'src') ?? '';
    const dark = [...body.matchAll(/<source\b[^>]*>/gi)].map((m) => m[0]).find((t) => /prefers-color-scheme:\s*dark/.test(attr(t, 'media') ?? ''));
    const stem = /^(.*)-light\.png$/.exec(src)?.[1];
    if (!stem) problems.push(`the picture with ${src || 'no image'} is not a -light.png screenshot`);
    else if (!dark) problems.push(`${src} has no dark variant (a <source media="(prefers-color-scheme: dark)">)`);
    else if (attr(dark, 'srcset') !== `${stem}-dark.png`) problems.push(`${src} has a dark source that is not ${stem}-dark.png`);
  }
  for (const name of SCREENS) {
    for (const theme of ['light', 'dark']) if (!used.has(`${SHOTS}${name}-${theme}.png`)) problems.push(`${SHOTS}${name}-${theme}.png is not in the README`);
  }
  return problems;
}

const real = {
  exists: (p) => fs.existsSync(path.join(REPO, p)),
  size: (p) => fs.statSync(path.join(REPO, p)).size,
};

const PIC = (name, alt = 'A screen.') => `<picture>\n  <source media="(prefers-color-scheme: dark)" srcset="${SHOTS}${name}-dark.png">\n  <img src="${SHOTS}${name}-light.png" alt="${alt}">\n</picture>\n`;
const GOOD = `# <img src="${ICON}" alt="" width="40" height="40"> nika\n\nIntro.\n\n${SCREENS.map((n) => PIC(n)).join('\n')}`;
const files = (list, size = 1000) => ({ exists: (p) => list.includes(p), size: () => size });
const ALL = [ICON, ...SCREENS.flatMap((n) => [`${SHOTS}${n}-light.png`, `${SHOTS}${n}-dark.png`])];

describe('README images', () => {
  test('(+) this repository: every image exists, light and dark, with alt text, under 300 KB, icon in the title', () => {
    const found = checkReadme(fs.readFileSync(path.join(REPO, 'README.md'), 'utf8'), real);
    assert.deepEqual(found, []);
  });

  test('(+) a README with the icon and every screenshot in both themes passes', () => {
    assert.deepEqual(checkReadme(GOOD, files(ALL)), []);
  });

  test('(−) a missing file is reported', () => {
    const found = checkReadme(GOOD, files(ALL.filter((p) => p !== `${SHOTS}rules-dark.png`)));
    assert.deepEqual(found, [`srcset ${SHOTS}rules-dark.png does not exist`]);
  });

  test('(−) a screenshot without its dark variant is reported, and so is a dark source that names another file', () => {
    const noDark = GOOD.replace(/<source[^>]*settings-dark\.png">\n/, '');
    assert.deepEqual(checkReadme(noDark, files(ALL)), [
      `${SHOTS}settings-light.png has no dark variant (a <source media="(prefers-color-scheme: dark)">)`,
      `${SHOTS}settings-dark.png is not in the README`,
    ]);
    const wrong = GOOD.replace('srcset="docs/screenshots/spawn-dark.png"', 'srcset="docs/screenshots/rules-dark.png"');
    assert.ok(checkReadme(wrong, files(ALL)).includes(`${SHOTS}spawn-light.png has a dark source that is not ${SHOTS}spawn-dark.png`));
  });

  test('(−) a screenshot with no alt text, an oversized one and a remote image are reported; the icon may have an empty alt', () => {
    assert.deepEqual(checkReadme(GOOD.replace('alt="A screen."', 'alt=""'), files(ALL)), [`${SHOTS}dashboard-light.png has no alt text`]);
    const big = checkReadme(GOOD, { exists: () => true, size: (p) => (p.endsWith('session-dark.png') ? MAX_BYTES + 1 : 10) });
    assert.deepEqual(big, [`${SHOTS}session-dark.png is over 300 KB`]);
    assert.ok(checkReadme(`${GOOD}<img src="https://example.org/x.png" alt="x">`, files(ALL)).includes('src https://example.org/x.png is not a file in the repository'));
  });

  test('(−) a title without the icon is reported, and a screen missing from the README', () => {
    assert.deepEqual(checkReadme(GOOD.replace(/^# .* nika/, '# nika'), files(ALL)), [`the title line has no ${ICON} icon`]);
    const fewer = GOOD.replace(PIC('spawn'), '');
    assert.deepEqual(checkReadme(fewer, files(ALL)), [`${SHOTS}spawn-light.png is not in the README`, `${SHOTS}spawn-dark.png is not in the README`]);
  });
});
